import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        final long MOD = 1000000007L;
        int[] length = new int[(int) n];
        long[] count = new long[(int) n];
        Arrays.fill(length, 1);
        Arrays.fill(count, 1);
        int best = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (a[j] < a[i]) {
                    if (length[j] + 1 > length[i]) {
                        length[i] = length[j] + 1;
                        count[i] = count[j];
                    } else if (length[j] + 1 == length[i]) {
                        count[i] = (count[i] + count[j]) % MOD;
                    }
                }
            }
            best = Math.max(best, length[i]);
        }
        long total = 0;
        for (int i = 0; i < n; i++) if (length[i] == best) total = (total + count[i]) % MOD;
        System.out.println(total);
    }
}
